package org.humanjourney.core.geography.map;
import java.util.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.npc.context.NpcContextStore;
/** Derived knowledge only: never changes discovery, geography or player progression. */
public final class MapServer {
 private record Key(long discovery,long data,String era){}
 private static final class Peer {int entityId;Key key;MapProjection.View view;long sequence;boolean force=true,warned;int requestTick=Integer.MIN_VALUE;}
 private static MinecraftServer owner;private static UUID session=UUID.randomUUID();private static long sequence,presentation,dataRevision=-1;private static String currentEra;
 private static final Map<UUID,Peer> peers=new HashMap<>();private static final LinkedHashMap<String,MapProjection.Factory> factories=new LinkedHashMap<>();private static final LinkedHashMap<Key,MapProjection.View> projections=new LinkedHashMap<>();
 public static void clear(){owner=null;session=UUID.randomUUID();sequence=presentation=0;currentEra=null;dataRevision=-1;peers.clear();factories.clear();projections.clear();}
 private static MapProjection.View view(Key key,DiscoveryLedger.Snapshot discovered){var data=NpcContextStore.state();if(dataRevision!=data.revision()){factories.clear();projections.clear();dataRevision=data.revision();}var cached=projections.get(key);if(cached!=null)return cached;var factory=factories.computeIfAbsent(key.era(),e->new MapProjection.Factory(data.data().geography(),e));while(factories.size()>4)factories.remove(factories.keySet().iterator().next());var result=factory.project(discovered);projections.put(key,result);while(projections.size()>4)projections.remove(projections.keySet().iterator().next());return result;}
 private static long labelEpoch(String era){if(!Objects.equals(currentEra,era)){currentEra=era;presentation++;}return presentation;}
 private static boolean send(ServerPlayer player,List<MapPackets.Frame> frames,Peer peer){for(var f:frames)if(!MapNetwork.send(f,player)){peer.force=true;if(!peer.warned){peer.warned=true;com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] Map geometry sync failed for {}; next update retries a full snapshot",player.getScoreboardName());}return false;}peer.warned=false;return true;}
 public static void sync(MinecraftServer server){if(owner!=server){clear();owner=server;}var online=server.getPlayerList().getPlayers();var ids=new HashSet<UUID>();for(var p:online)ids.add(p.getUUID());peers.keySet().retainAll(ids);var discovered=SavedDiscovery.get(server).snapshot();long data=NpcContextStore.state().revision();for(var player:online){var id=player.getUUID();if(!GeographyServer.roles(player).participant()){var peer=peers.get(id);if(peer!=null){var h=new MapPackets.Header(session,++sequence,discovered.revision(),data,presentation);if(send(player,MapPackets.frames(h,MapPackets.Mode.CLEAR,0,List.of(),List.of()),peer))peers.remove(id);}continue;}var peer=peers.computeIfAbsent(id,k->new Peer());String era=GeographyServer.era(player);var key=new Key(discovered.revision(),data,era);if(!peer.force&&peer.entityId==player.getId()&&key.equals(peer.key))continue;var projected=view(key,discovered);boolean full=peer.force||peer.key==null||peer.entityId!=player.getId()||peer.key.data()!=key.data()||!peer.key.era().equals(key.era());var mode=discovered.macros().isEmpty()&&discovered.locals().isEmpty()?MapPackets.Mode.CLEAR:full?MapPackets.Mode.FULL:MapPackets.Mode.DELTA;var updates=new ArrayList<MapArea>();var removed=new ArrayList<MapArea.Key>();if(mode==MapPackets.Mode.FULL)updates.addAll(projected.areas().values());else if(mode==MapPackets.Mode.DELTA){for(var entry:projected.areas().entrySet())if(!entry.getValue().equals(peer.view.areas().get(entry.getKey())))updates.add(entry.getValue());for(var previous:peer.view.areas().keySet())if(!projected.areas().containsKey(previous))removed.add(previous);}var h=new MapPackets.Header(session,++sequence,discovered.revision(),data,labelEpoch(era));if(send(player,MapPackets.frames(h,mode,mode==MapPackets.Mode.DELTA?peer.sequence:0,updates,removed),peer)){peer.key=key;peer.view=projected;peer.sequence=h.sequence();peer.entityId=player.getId();peer.force=false;}}
 }
 public static void request(ServerPlayer player){if(!GeographyServer.roles(player).participant())return;var server=player.level().getServer();if(server==null)return;if(owner!=server){clear();owner=server;}var peer=peers.computeIfAbsent(player.getUUID(),k->new Peer());int tick=server.getTickCount();if(peer.requestTick!=Integer.MIN_VALUE&&tick>=peer.requestTick&&tick-peer.requestTick<60)return;peer.requestTick=tick;peer.force=true;}
 public static String describe(ServerPlayer player){var discovered=SavedDiscovery.get(player.level().getServer()).snapshot();var key=new Key(discovered.revision(),NpcContextStore.state().revision(),GeographyServer.era(player));var projected=view(key,discovered);long macros=projected.areas().values().stream().filter(a->a.kind()==MapArea.Kind.MACRO).count();return "Map geometry: macros="+macros+" locals="+(projected.areas().size()-macros)+" | data="+key.data()+" discovery="+key.discovery()+" | stale/unresolvable="+projected.staleMacros()+"/"+projected.staleLocals();}
 private MapServer(){}
}
